{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Verapamil, a structurally related dimethoxyphenyl tertiary amine, has an absolute oral bioavailability of 34% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "Noscapine, a dimethoxy-substituted chiral alkaloid, has an absolute oral bioavailability of 30% in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C67"],
      "claim": "Sulpiride, an amide/amine drug with similar polarity, has an oral bioavailability of 35% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Encainide, an aromatic amide/amine drug, has an absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "Alfentanil, a basic amide drug, has an absolute oral bioavailability of 0.42 ± 0.15 in volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C60"],
      "claim": "Levosulpiride, a close sulpiride analog, has an absolute oral bioavailability of 23.4% in Chinese volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Valbenazine, a dimethoxy-substituted chiral CNS drug, has an absolute oral bioavailability of approximately 49% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "Colchicine, a polycyclic alkaloid with multiple methoxy groups, has a mean absolute oral bioavailability of 55% in elderly subjects, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Codeine, a basic opioid with substantial first-pass metabolism, has an oral bioavailability of 42-71% in healthy volunteers, supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C71"],
      "claim": "Verapamil in one study averaged 19.4% oral bioavailability in normal young men, just below the 20% threshold, providing limited contradictory evidence.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high (F >= 20%) because multiple structurally related analogs—verapamil, noscapine, sulpiride, encainide, alfentanil, levosulpiride, valbenazine, colchicine, and codeine—show absolute oral bioavailability mostly in the 23-55% range; only occasional verapamil values fall just below 20%.",
  "evidence_gaps": [
    "No direct experimental bioavailability record for the query molecule itself.",
    "The query's exact identity is not established; structural analogy relies on inferred similarity to verapamil-like dimethoxyphenyl amines and related CNS drugs.",
    "Verapamil, the closest analog, has values straddling the 20% threshold (18-20%, 19.4%, 22-38%), creating borderline uncertainty.",
    "No formulation, dose, or first-pass metabolism data specific to the query are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

